/// The types of a file鈥檚 time fields. These three fields are standard
/// across most (all?) operating systems.
#[derive(PartialEq, Eq, Debug, Copy, Clone)]
pub enum TimeType {
    /// The file鈥檚 modified time (`st_mtime`).
    Modified,

    /// The file鈥檚 changed time (`st_ctime`)
